def load(index):
    """Monthly DataFrame on `index` (first day of each month) with what was known at the end of each month."""
    embig = pd.Series([float(x) for x in EMBIG.split(",")], index=pd.date_range("2006-08-01", periods=242, freq="MS"))
    fx = pd.Series([float(x) for x in FX.split(",")], index=pd.date_range("2006-01-01", periods=249, freq="MS"))
    fb = pd.Series({pd.Timestamp(f"20{k[:2]}-{k[2:]}-01"): float(v) for k, v in (x.split(":") for x in FOREIGN_BONOS.split())})
    return pd.DataFrame({"embig": embig, "fx": fx, "foreign_bonos": fb}).reindex(index)
